@@ -8,16 +8,32 @@ import { create_derived } from '../utils.js';
 import { get_value } from './shared/declarations.js';
 import { build_expression } from './shared/utils.js';

+/**
+ * @param {AST.ConstTag} node
+ * @param {ComponentContext} context
+ */
+function create_derived_from(node, context, init, async) {
+	if (async) {
+		let call = b.call('$.async_derived', b.thunk(init, true));
+		call = b.call(b.await(b.call('$.save', call)));
+		return call;
+	}
+
+	return create_derived(context.state, b.thunk(init));
+}
